import{_ as a,o,c as s,a2 as i}from"./chunks/framework.DCVnL8g5.js";const m=JSON.parse('{"title":"Buenas prácticas","description":"","frontmatter":{},"headers":[],"relativePath":"data-engineering/iceberg/08-buenas-practicas.md","filePath":"data-engineering/iceberg/08-buenas-practicas.md","lastUpdated":1789040978000,"isDraft":false}'),r={name:"data-engineering/iceberg/08-buenas-practicas.md"};function t(n,e,c,l,d,p){return o(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="buenas-practicas" tabindex="-1">Buenas prácticas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas prácticas&quot;">​</a></h1><p>Cierra el recorrido sobre <code>local.analytics.events</code>: diseño, writes, catálogo, mantenimiento y compatibilidad. Iceberg es el formato; el motor y el catálogo son <em>tuyos</em>.</p><p>Documentación: <a href="https://iceberg.apache.org/docs/latest/" target="_blank" rel="noreferrer">docs</a>, <a href="https://iceberg.apache.org/spec/" target="_blank" rel="noreferrer">spec</a>, <a href="https://iceberg.apache.org/docs/latest/spark-procedures/" target="_blank" rel="noreferrer">procedures</a>, <a href="https://iceberg.apache.org/docs/latest/" target="_blank" rel="noreferrer">multi-engine</a>.</p><h2 id="diseno" tabindex="-1">Diseño <a class="header-anchor" href="#diseno" aria-label="Permalink to &quot;Diseño&quot;">​</a></h2><ul><li>Esquema con <strong>IDs</strong>: evolve con <code>ALTER</code> (<code>ADD</code>/<code>RENAME</code>/<code>DROP</code>/<code>TYPE</code>). No reutilices IDs ni simules un rename con drop+add.</li><li>Partition <strong>transforms</strong> (<code>days(event_time)</code>, <code>identity</code>, <code>bucket</code>) alineados al filtro real. No sobreparticiones por ids únicos.</li><li>Evolucionar el spec no reescribe el histórico. Compáctalo aparte si el layout viejo duele.</li><li><code>format-version</code> mínima que cubra tus deletes/motores. <strong>v1–v3 adoptadas; v4 no.</strong> No actives v3 “por las features del blog” si Trino/Flink aún no las leen.</li></ul><h2 id="escrituras" tabindex="-1">Escrituras <a class="header-anchor" href="#escrituras" aria-label="Permalink to &quot;Escrituras&quot;">​</a></h2><ul><li>Controla el tamaño de fichero (<code>write.target-file-size-bytes</code>, distribución <code>hash</code>/<code>range</code>, no un append de 40 filas cada segundo sin compactar).</li><li><code>writeTo(...).append()</code> para tablas de catálogo. Reserva <code>format(&quot;iceberg&quot;)</code> para casos path aislados.</li><li><code>INSERT OVERWRITE</code> con alcance consciente (dynamic vs static). <code>MERGE</code> reescribe ficheros afectados: predica bien y deduplica el source.</li><li>SQL <code>MERGE</code>/<code>UPDATE</code>/<code>DELETE</code> necesitan extensions en Spark 3.x. DataFrame <code>mergeInto</code> es Spark 4.0+.</li></ul><h2 id="catalogo" tabindex="-1">Catálogo <a class="header-anchor" href="#catalogo" aria-label="Permalink to &quot;Catálogo&quot;">​</a></h2><ul><li>Elige según <strong>cuántos motores y writers</strong>: Hadoop para un solo proceso de laboratorio; REST (u Hive/JDBC bien operados) cuando hay que commitear en serio.</li><li>Catálogo ≠ S3. Alta disponibilidad y backups del <strong>metastore/REST</strong>, no solo del warehouse.</li><li>Cloud catalogs (Glue, etc.) son implementaciones, no el estándar Iceberg.</li></ul><h2 id="mantenimiento" tabindex="-1">Mantenimiento <a class="header-anchor" href="#mantenimiento" aria-label="Permalink to &quot;Mantenimiento&quot;">​</a></h2><ul><li><code>rewrite_data_files</code> (binpack; sort/z-order solo medidos).</li><li><code>rewrite_manifests</code> si el planning se ahoga en manifests chicos.</li><li><code>expire_snapshots</code> con retención que cubra time travel <strong>y</strong> jobs largos; respeta branches/tags.</li><li><code>remove_orphan_files</code> con <code>dry_run</code> y <code>older_than</code> holgado. Nunca en medio de un write.</li><li>Observa <code>.snapshots</code>, <code>.files</code>, <code>.manifests</code>: recuento de snapshots, ficheros por partición, manifests.</li></ul><h2 id="compatibilidad" tabindex="-1">Compatibilidad <a class="header-anchor" href="#compatibilidad" aria-label="Permalink to &quot;Compatibilidad&quot;">​</a></h2><ul><li>Antes de subir format-version o table features, verifica <strong>cada</strong> motor que lee/escribe.</li><li>“Funciona en Spark” ≠ mismo <code>MERGE</code>, mismos deletes, mismos types en Flink/Trino.</li><li>No documentes spec v4 como estable.</li></ul><h2 id="observabilidad" tabindex="-1">Observabilidad <a class="header-anchor" href="#observabilidad" aria-label="Permalink to &quot;Observabilidad&quot;">​</a></h2><ul><li>Crecimiento de <code>metadata/</code> y de manifests.</li><li>Small files tras streaming.</li><li>Fallos de commit / retries (conflicto OCC).</li><li>Time travel que de repente falla: alguien expiró el snapshot.</li></ul><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery&quot;">​</a></h2><ul><li>Snapshot + tag ayudan a <strong>inspeccionar y revertir</strong> (<code>rollback_to_snapshot</code>) dentro de la retención.</li><li>No sustituyen copiar el warehouse y el catálogo a otro sitio.</li><li>No parchees metadata JSON a mano.</li></ul><h2 id="recorrido" tabindex="-1">Recorrido <a class="header-anchor" href="#recorrido" aria-label="Permalink to &quot;Recorrido&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tabla events</span></span>
<span class="line"><span>  → snapshots / manifests</span></span>
<span class="line"><span>  → days(event_time)</span></span>
<span class="line"><span>  → IDs y ALTER</span></span>
<span class="line"><span>  → Spark writeTo / SQL</span></span>
<span class="line"><span>  → catálogo (puntero)</span></span>
<span class="line"><span>  → rewrite / expire / orphans</span></span>
<span class="line"><span>  → operación</span></span></code></pre></div><p>Spark enseñó las APIs; Iceberg sigue siendo el formato.</p>`,20)])])}const h=a(r,[["render",t]]);export{m as __pageData,h as default};
